def transform(grid):
    h, w = len(grid), len(grid[0])
    hr = [r for r in range(h) if len(set(grid[r])) == 1]
    vc = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    rb = [-1] + hr + [h]
    cb = [-1] + vc + [w]
    rows = [(a + 1, b) for a, b in zip(rb, rb[1:]) if b > a + 1]
    cols = [(a + 1, b) for a, b in zip(cb, cb[1:]) if b > a + 1]
    if not rows or not cols:
        return [row[:] for row in grid]
    from collections import Counter
    tiles = []
    for ri, (r0, r1) in enumerate(rows):
        for ci, (c0, c1) in enumerate(cols):
            vals = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)]
            bg = Counter(vals).most_common(1)[0][0]
            tiles.append((sum(v != bg for v in vals), ri, ci, bg))
    _, si, sj, bg = max(tiles)
    sr0, sr1 = rows[si]
    sc0, sc1 = cols[sj]
    out = [row[:] for row in grid]
    for r0, r1 in rows:
        for c0, c1 in cols:
            for dr in range(min(r1-r0, sr1-sr0)):
                for dc in range(min(c1-c0, sc1-sc0)):
                    v = grid[sr0+dr][sc0+dc]
                    if v != bg:
                        out[r0+dr][c0+dc] = v
    return out
